<script setup lang="ts">
import {t} from '../i18n'
import {readOnly,saving} from '../composables/useState'
import {configStatus,applying,useConfigStatusPolling,confirmPanelAccess,finishAccessRule,recoveryError,recoveryBusy} from '../composables/useConfigStatus'
import {retryApply} from '../composables/useApply'
useConfigStatusPolling()
</script>
<template><div v-if="configStatus.stage!=='applied'||configStatus.port_confirmation||configStatus.access_confirmation" class="config-status-bar" :class="configStatus.stage" role="status"><template v-if="configStatus.stage!=='applied'"><span :class="{spinning:applying}">{{applying?'◌':configStatus.stage==='failed'?'!':'✓'}}</span><div><strong>{{t(configStatus.message||'正在读取配置状态…')}}</strong><small v-if="configStatus.updated">{{new Date(configStatus.updated).toLocaleString()}}</small></div><button v-if="configStatus.stage==='failed'" class="secondary" :disabled="readOnly||saving||applying" @click="retryApply">{{t('重试应用')}}</button><a v-if="configStatus.stage==='failed'" href="#config-history">{{t('配置历史')}}</a></template><div v-if="configStatus.port_confirmation" class="port-confirmation"><strong>{{t('请确认新端口可以访问')}}</strong><p>{{configStatus.port_confirmation.old_port}} → {{configStatus.port_confirmation.new_port}} · {{t('截止时间')}} {{new Date(configStatus.port_confirmation.deadline*1000).toLocaleTimeString()}} · {{t('超时将自动恢复旧端口')}}</p><button class="primary" :disabled="readOnly" @click="confirmPanelAccess">{{t('确认当前访问正常')}}</button></div><section v-if="configStatus.access_confirmation" class="access-rule-confirmation"><strong>{{t('请确认面板访问限制')}}</strong><p>{{configStatus.access_confirmation.domain}} · {{t('截止时间')}} {{new Date(configStatus.access_confirmation.deadline*1000).toLocaleTimeString()}}</p><p>{{t('需从该域名访问后确认，超时自动恢复原规则。局域网入口可以取消修改。')}}</p><button class="primary" :disabled="readOnly||applying||recoveryBusy||saving" @click="finishAccessRule()">{{t('确认域名可访问')}}</button><button class="secondary" :disabled="readOnly||applying||recoveryBusy||saving" @click="finishAccessRule(true)">{{t('取消修改并恢复')}}</button><p v-if="recoveryError" role="alert">{{recoveryError}}</p></section></div></template>
